import { Meta } from "@storybook/react";
import { NavLink } from "../NavLink";

export default {
  title: "@travelmakers/core/General/NavBar/NavLink",
  component: NavLink,
  argTypes: {
    href: {
      control: { type: "text" },
      defaultValue: "#",
      description: "NavLink href",
      table: {
        type: {
          summary: "string",
        },
      },
    },
    label: {
      control: { type: "text" },
      defaultValue: "\uB808\uC774\uBE14",
      description: "NavLink \uD0C0\uC774\uD2C0",
      table: {
        type: {
          summary: "string",
        },
      },
    },
    isDisable: {
      type: "boolean",
      defaultValue: "false",
      description: "NavLink disabled",
      table: {
        type: {
          summary: "boolean",
        },
      },
    },
  },
} as Meta;

export const Default = (props) => {
  return <NavLink {...props} />;
};



