import { Meta } from "@storybook/react";
import { useState } from "react";
import { SelectButton } from "../SelectButton";

const data = ["\uC120\uD0DD1", "\uC120\uD0DD2"];

export default {
  title: "@travelmakers/core/General/Selection/SelectButton/SelectButton",
  component: SelectButton,
  argTypes: {
    label: {
      control: {
        type: "text",
      },
      description: "SelectButton \uB77C\uBCA8",
      table: {
        type: {
          summary: "string",
        },
      },
    },
    feedback: {
      control: {
        type: "text",
      },
      description: "SelectButton \uCD94\uAC00 \uC124\uBA85",
      table: {
        type: {
          summary: "string",
        },
      },
    },
    items: {
      control: { type: "array" },
      description:
        "SelectButton\uC5D0 \uD45C\uC2DC\uB420 \uB9AC\uC2A4\uD2B8 \uC785\uB2C8\uB2E4. SelectButton.Item\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
      table: {
        type: {
          summary: "SelectButtonItem[]",
        },
      },
    },
    callout: {
      control: { type: "object" },
      description: "SelectButton\uC640 \uD568\uAED8 \uC0AC\uC6A9\uB418\uB294 SelectButton.Callout\uC785\uB2C8\uB2E4.",
      table: {
        type: {
          summary: "Callout[]",
        },
      },
    },
    isVisibleLabel: {
      control: { type: "boolean" },
      description: "SelectButton\uC758 label prop \uB178\uCD9C \uC5EC\uBD80",
      table: {
        type: {
          summary: "boolean",
        },
      },
    },
  },
} as Meta;

export const Default = (props) => {
  const [currentTab, setCurrentTab] = useState("\uC120\uD0DD1");

  const _items = data.map((item, idx) => (
    <SelectButton.Item
      key={idx}
      content={item}
      value={item}
      checked={currentTab === item}
      onChange={(e) => {
        const { value } = e.target as HTMLInputElement;

        setCurrentTab(value);
      }}
    />
  ));

  return (
    <SelectButton
      {...props}
      label={props.label ?? "\uC120\uD0DD \uADF8\uB8F9"}
      items={_items}
    />
  );
};;

